def allow_request(state, actor, now, limit=2, window=60):
    if not isinstance(now, int) or now < 0 or limit < 1 or window < 1:
        raise ValueError('use nonnegative integer time and positive limit/window')
    slot = now // window
    old_slot, count = state.get(actor, (slot, 0))
    if old_slot != slot:
        count = 0
    if count >= limit:
        return {'status': 429, 'retry_after': (slot + 1) * window - now}
    state[actor] = (slot, count + 1)
    return {'status': 200}

