state = {}
assert allow_request(state, 'ava', 59) == {'status': 200}
assert allow_request(state, 'ava', 59) == {'status': 200}
assert allow_request(state, 'ava', 59) == {'status': 429, 'retry_after': 1}
assert allow_request(state, 'ava', 60) == {'status': 200}
print('PASS: limit and boundary')
assert allow_request(state, 'bo', 60) == {'status': 200}
assert allow_request(state, 'ava', 60) == {'status': 200}
assert allow_request(state, 'ava', 60) == {'status': 429, 'retry_after': 60}
print('PASS: independent actor and full wait')
try:
    allow_request(state, 'ava', -1)
except ValueError:
    pass
else:
    raise AssertionError('invalid time must fail')
print('PASS: invalid clock')
